/****** Object:  View [dbo].[FoodCalories]    Script Date: 2026/5/7 下午 04:13:38 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[FoodCalories] AS

SELECT
	C.CategoryName,
	F.FoodName,
	N.Kcal
FROM FoodCategories as C
LEFT JOIN Foods as F ON C.Id=F.CategoryId
LEFT JOIN NutrientReferenceValues as N ON F.Id=N.FoodId
